const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const upperArrowLake = ee.Geometry.Polygon([
    [-118.2, 50.2], [-117.8, 50.2], [-117.8, 50.5], [-118.2, 50.5], [-118.2, 50.2]
  ]);

  const date = '2018-10-22';
  const morningStart = ee.Date(date).advance(6, 'hour'); // 6 AM
  const morningEnd = ee.Date(date).advance(10, 'hour');  // 10 AM
  const afternoonStart = ee.Date(date).advance(13, 'hour'); // 1 PM
  const afternoonEnd = ee.Date(date).advance(17, 'hour');   // 5 PM

  // 2. Data Acquisition - Sentinel-2 with cloud probability
  const s2Col = ee.ImageCollection('COPERNICUS/S2_CLOUD_PROBABILITY')
    .filterBounds(upperArrowLake)
    .filterDate('2018-10-22', '2018-10-23');

  // Check if collection is empty
  const collectionSize = s2Col.size().getInfo();
  if (collectionSize === 0) {
    print("No Sentinel-2 images found for October 22, 2018");
    print("<answer>C1</answer>");
    return;
  }

  // Separate morning and afternoon images
  const morningImages = s2Col.filterDate(morningStart, morningEnd);
  const afternoonImages = s2Col.filterDate(afternoonStart, afternoonEnd);

  const morningCount = morningImages.size().getInfo();
  const afternoonCount = afternoonImages.size().getInfo();

  print(`Morning images: ${morningCount}, Afternoon images: ${afternoonCount}`);

  // Check if we have images for both periods
  if (morningCount === 0 || afternoonCount === 0) {
    print("Missing images for one or both time periods");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate cloud coverage
  function calculateCloudCoverage(images) {
    const mosaic = images.mosaic();
    const cloudProb = mosaic.select('probability');

    // Count pixels with high cloud probability (>30%)
    const cloudMask = cloudProb.gt(30);
    const stats = cloudMask.reduceRegion({
      reducer: ee.Reducer.sum().combine(ee.Reducer.count(), null, true),
      geometry: upperArrowLake,
      scale: 100,
      maxPixels: 1e9
    });

    const cloudPixels = stats.get('probability_sum').getInfo();
    const totalPixels = stats.get('probability_count').getInfo();

    if (totalPixels === 0) {
      return {coverage: null, validPixels: 0};
    }

    const coverage = (cloudPixels / totalPixels) * 100;
    return {coverage: coverage, validPixels: totalPixels};
  }

  const morningStats = calculateCloudCoverage(morningImages);
  const afternoonStats = calculateCloudCoverage(afternoonImages);

  print(`Morning: ${morningStats.coverage?.toFixed(1)}% cloud (${morningStats.validPixels} px)`);
  print(`Afternoon: ${afternoonStats.coverage?.toFixed(1)}% cloud (${afternoonStats.validPixels} px)`);

  // 4. Validation & Final Answer
  if (morningStats.validPixels === 0 || afternoonStats.validPixels === 0) {
    print("No valid pixels in one or both time periods");
    print("<answer>C2</answer>");
  } else if (morningStats.coverage === null || afternoonStats.coverage === null || 
             isNaN(morningStats.coverage) || isNaN(afternoonStats.coverage)) {
    print("Invalid cloud coverage calculation");
    print("<answer>C3</answer>");
  } else if (afternoonStats.coverage < morningStats.coverage) {
    print("Afternoon fog coverage is lower than morning");
    print("<answer>A</answer>");
  } else {
    print("Afternoon fog coverage is not lower than morning");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
